begin;
create temporary table kept_tournaments as select jsonb_build_object('tournaments',(select jsonb_agg(to_jsonb(t)-'display_order' order by id) from public.paid_tournaments t where id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'predictions',(select jsonb_agg(to_jsonb(g) order by tournament_id,slot) from public.paid_tournament_predictions g where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'entries',(select jsonb_agg(to_jsonb(e) order by tournament_id,profile_id) from public.paid_tournament_entries e where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'picks',(select jsonb_agg(to_jsonb(p) order by tournament_id,slot,profile_id) from public.paid_tournament_picks p where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'orders',(select jsonb_agg(to_jsonb(o) order by id) from public.infinitepay_orders o where tournament_id is distinct from '671f995b-18bf-4c49-a706-caff6e580e19'::uuid), 'profiles',(select jsonb_agg(to_jsonb(p) order by id) from public.public_profiles p)) as snapshot;

do $$
declare choices jsonb; after_snapshot jsonb; subject uuid; result jsonb;
begin
 if exists(select 1 from public.paid_tournaments where id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.paid_tournament_predictions where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.paid_tournament_entries where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.paid_tournament_picks where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.infinitepay_orders where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.tournament_bot_pick_log where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') or exists(select 1 from public.admin_tournament_pick_corrections where tournament_id='671f995b-18bf-4c49-a706-caff6e580e19') then raise exception 'Cards data remains'; end if;
 choices:=public.available_paid_tournaments_json();
 if jsonb_array_length(choices)<>2 or choices->0->>'id'<>'2e0617ac-f47a-4abd-aae8-68b4c59aa12d' or choices->1->>'id'<>'2270fca1-406c-4da0-8582-20c20520a44c' then raise exception 'Incorrect arrow order'; end if;
 select auth_user_id into subject from public.private_profiles where profile_id='4325ba8c-8b6b-9635-429c-cef8c63ac2d4';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',subject,'role','authenticated','email',(select owner_email from public.app_config where singleton))::text,true);
 if public.get_finishing_tournament(null)->>'id'<>'2e0617ac-f47a-4abd-aae8-68b4c59aa12d' or public.get_admin_finishing_tournament(null)->>'id'<>'2e0617ac-f47a-4abd-aae8-68b4c59aa12d' or public.get_admin_player_tournament_picks('4325ba8c-8b6b-9635-429c-cef8c63ac2d4',null)->>'id'<>'2e0617ac-f47a-4abd-aae8-68b4c59aa12d' then raise exception 'Default selection not Champions'; end if;
 result:=public.get_finishing_tournament('2270fca1-406c-4da0-8582-20c20520a44c');
 if result->>'enrolled'<>'true' or result->>'entryCents'<>'444' or jsonb_array_length(result->'predictions')<>20 then raise exception 'EL CLASICO entry lost'; end if;
 select jsonb_build_object('tournaments',(select jsonb_agg(to_jsonb(t)-'display_order' order by id) from public.paid_tournaments t where id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'predictions',(select jsonb_agg(to_jsonb(g) order by tournament_id,slot) from public.paid_tournament_predictions g where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'entries',(select jsonb_agg(to_jsonb(e) order by tournament_id,profile_id) from public.paid_tournament_entries e where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'picks',(select jsonb_agg(to_jsonb(p) order by tournament_id,slot,profile_id) from public.paid_tournament_picks p where tournament_id<>'671f995b-18bf-4c49-a706-caff6e580e19'), 'orders',(select jsonb_agg(to_jsonb(o) order by id) from public.infinitepay_orders o where tournament_id is distinct from '671f995b-18bf-4c49-a706-caff6e580e19'::uuid), 'profiles',(select jsonb_agg(to_jsonb(p) order by id) from public.public_profiles p)) into after_snapshot;
 if after_snapshot is distinct from (select snapshot from kept_tournaments) then raise exception 'Unrelated data changed'; end if;
 if has_function_privilege('authenticated','public.available_paid_tournaments_json()','EXECUTE') or has_function_privilege('anon','public.available_paid_tournaments_json()','EXECUTE') then raise exception 'Private helper exposed'; end if;
end $$;
select 'PASS: Champions first across player/admin/correction RPCs; cards and linked data removed; EL CLASICO enrollment, other tournaments, profiles and payments preserved' as checks;
rollback;
